(function ($) {
    'use strict';

    // Clone witness
    $('.btn-clone').on('click', function () {
        var newelement = $(".clone-witness").eq(0).clone();
        var num = $('.clone-witness').length;
        var newNum = num + 1;
        newelement.find('input').each(function (i) {
            $(this).attr('name', $(this).attr('name') + newNum);
            $(this).attr('id', $(this).attr('id') + newNum);
        });
        newelement.find('label').each(function (i) {
            $(this).attr('id', $(this).attr('id') + newNum);
        });
        newelement.find('input').val('');
        newelement.append('<div class="form-group"><button class="btn btn-sm btn-block btn-danger btn-remove" type="button"><i class="icon-minus"></i> Remove this witness</button></div>')
        $('.clone-witness').last().after(newelement);
    });

    // Remove witness
    $("body").on("click", ".btn-remove", function () {
        $(this).parents(".clone-witness").remove();
    });

    // Anonymous Modal
    $('#reportForm').on('submit', function (e) {
        var selectedValue = $("#UpdatedOnIncidentMethod").val();
        if (selectedValue == "Anonymous") {
            $('#AnonymousModal').modal('show');
            e.preventDefault();
        }
    });

    // Collapse
    $("#SupportingEvidence").on('change', function () {
        var selectedValue = $("#SupportingEvidence").val();
        if (selectedValue == "Yes") {
            $(".collapseSupportingEvidence").slideDown(500);
            $('.collapseSupportingEvidence').addClass('show');
            $('.collapseSupportingEvidence').removeClass('hide');
        } else {
            $(".collapseSupportingEvidence").slideUp(500);
            $('.collapseSupportingEvidence').removeClass('show');
            $('.collapseSupportingEvidence').addClass('hide');
        }
    });
    $("#FileAttachment").on('change', function () {
        var selectedValue = $("#FileAttachment").val();
        if (selectedValue == "Yes") {
            $("#collapseFileAttachment").slideDown(500);
            $('#collapseFileAttachment').addClass('show');
            $('#collapseFileAttachment').removeClass('hide');
        } else {
            $("#collapseFileAttachment").slideUp(500);
            $('#collapseFileAttachment').removeClass('show');
            $('#collapseFileAttachment').addClass('hide');
        }
    });
    $("#HaveWitness").on('change', function () {
        var selectedValue = $("#HaveWitness").val();
        if (selectedValue == "Yes") {
            $("#collapseHaveWitness").slideDown(500);
            $('#collapseHaveWitness').addClass('show');
            $('#collapseHaveWitness').removeClass('hide');
        } else {
            $("#collapseHaveWitness").slideUp(500);
            $('#collapseHaveWitness').removeClass('show');
            $('#collapseHaveWitness').addClass('hide');
        }
    });
    $("#UpdatedOnIncident").on('change', function () {
        var selectedValue = $("#UpdatedOnIncident").val();
        if (selectedValue == "Yes") {
            $("#collapseUpdatedOnIncident").slideDown(500);
            $('#collapseUpdatedOnIncident').addClass('show');
            $('#collapseUpdatedOnIncident').removeClass('hide');
        } else {
            $("#collapseUpdatedOnIncident").slideUp(500);
            $('#collapseUpdatedOnIncident').removeClass('show');
            $('#collapseUpdatedOnIncident').addClass('hide');
        }
    });
    $("#UpdatedOnIncidentMethod").on('change', function () {
        var selectedValue = $("#UpdatedOnIncidentMethod").val();
        if (selectedValue == "Email") {
            $("#collapseUpdatedOnIncidentMethodEmail").slideDown(500);
            $('#collapseUpdatedOnIncidentMethodEmail').addClass('show');
            $('#collapseUpdatedOnIncidentMethodEmail').removeClass('hide');
        } else {
            $("#collapseUpdatedOnIncidentMethodEmail").slideUp(500);
            $('#collapseUpdatedOnIncidentMethodEmail').removeClass('show');
            $('#collapseUpdatedOnIncidentMethodEmail').addClass('hide');
        }
    });
    $("#UpdatedOnIncidentMethod").on('change', function () {
        var selectedValue = $("#UpdatedOnIncidentMethod").val();
        if (selectedValue == "Phone") {
            $("#collapseUpdatedOnIncidentMethodPhone").slideDown(500);
            $('#collapseUpdatedOnIncidentMethodPhone').addClass('show');
            $('#collapseUpdatedOnIncidentMethodPhone').removeClass('hide');
        } else {
            $("#collapseUpdatedOnIncidentMethodPhone").slideUp(500);
            $('#collapseUpdatedOnIncidentMethodPhone').removeClass('show');
            $('#collapseUpdatedOnIncidentMethodPhone').addClass('hide');
        }
    });
})(jQuery);